// src/api/automations.ts
import { api } from './client';

export type TriggerEvent =
  | 'contact.created'
  | 'contact.updated'
  | 'contact.tag_added'
  | 'company.created'
  | 'company.updated'
  | 'lead.created'
  | 'lead.updated'
  | 'lead.status_changed'
  | 'lead.assigned'
  | 'sale.created'
  | 'sale.updated'
  | 'sale.status_changed'
  | 'project.created'
  | 'project.status_changed'
  | 'task.created'
  | 'task.updated'
  | 'task.status_changed'
  | 'report.scheduled'
  | 'scheduled'
  | 'email.received'
  | 'email.sent'
  | 'telegram.message_received'
  | 'note.created'
  | 'custom_object.record_created'
  | 'custom_object.record_updated'
  | 'custom_object.status_changed';

export type ActionType =
  | 'create_task'
  | 'assign_task'
  | 'send_email'
  | 'send_telegram'
  | 'send_notification'
  | 'update_field'
  | 'add_tag'
  | 'remove_tag'
  | 'change_status'
  | 'assign_user'
  | 'trigger_webhook'
  | 'create_note'
  | 'send_report';

export interface Condition {
  field: string;
  operator:
    | 'equals'
    | 'not_equals'
    | 'contains'
    | 'not_contains'
    | 'greater_than'
    | 'less_than'
    | 'greater_or_equal'
    | 'less_or_equal'
    | 'is_empty'
    | 'is_not_empty'
    | 'starts_with'
    | 'ends_with';
  value?: any;
}

export interface Action {
  type: ActionType;
  config: Record<string, any>;
}

export interface Automation {
  id: string;
  tenantId: string;
  name: string;
  description: string | null;
  triggerEvent: TriggerEvent;
  conditions: Condition[] | null;
  actions: Action[];
  isActive: boolean;
  executionCount: number;
  errorCount: number;
  lastExecutedAt: string | null;
  lastError: string | null;
  maxExecutions: number | null;
  cooldownSeconds: number | null;
  meta?: Record<string, unknown> | null;
  createdAt: string;
  updatedAt: string;
}

export interface AutomationExecution {
  id: string;
  tenantId: string;
  automationId: string;
  triggerEvent: TriggerEvent;
  triggerData: any;
  entityType: string | null;
  entityId: string | null;
  status: 'pending' | 'success' | 'error' | 'skipped';
  errorMessage: string | null;
  executionResult: any | null;
  actionsExecuted: number;
  createdAt: string;
  automation?: Pick<Automation, 'id' | 'name'>;
}

export interface AutomationUsageStats {
  periodDays: number;
  since: string;
  executions: {
    total: number;
    success: number;
    error: number;
    pending: number;
    skipped: number;
  };
  byTrigger: Array<{ triggerEvent: string; count: number }>;
  topAutomations: Array<{ automationId: string; name: string; runs: number }>;
  automations: { total: number; active: number };
}

export interface CreateAutomationDto {
  name: string;
  description?: string;
  triggerEvent: TriggerEvent;
  conditions?: Condition[];
  actions: Action[];
  isActive?: boolean;
  maxExecutions?: number;
  cooldownSeconds?: number;
  meta?: Record<string, unknown>;
}

export interface UpdateAutomationDto extends Partial<CreateAutomationDto> {}

export async function fetchAutomations(isActive?: boolean): Promise<Automation[]> {
  const res = await api.get<Automation[]>('/automations', {
    params: isActive !== undefined ? { isActive } : {},
  });
  return res;
}

export async function fetchAutomation(id: string): Promise<Automation> {
  const res = await api.get<Automation>(`/automations/${id}`);
  return res;
}

export async function createAutomation(dto: CreateAutomationDto): Promise<Automation> {
  const res = await api.post<Automation>('/automations', dto);
  return res;
}

export async function updateAutomation(
  id: string,
  dto: UpdateAutomationDto,
): Promise<Automation> {
  const res = await api.patch<Automation>(`/automations/${id}`, dto);
  return res;
}

export async function deleteAutomation(id: string): Promise<void> {
  await api.delete(`/automations/${id}`);
}

export async function fetchAutomationExecutions(
  automationId?: string,
  limit?: number,
  status?: string,
): Promise<AutomationExecution[]> {
  if (automationId) {
    return api.get<AutomationExecution[]>(`/automations/${automationId}/executions`, {
      params: { limit, status },
    });
  }
  return api.get<AutomationExecution[]>('/automations/executions', {
    params: { limit, status },
  });
}

export async function fetchAutomationUsageStats(
  days?: number,
): Promise<AutomationUsageStats> {
  return api.get<AutomationUsageStats>('/automations/usage', {
    params: days !== undefined ? { days } : {},
  });
}

// src/pages/automations/AutomationsPage.tsx
import React, { useMemo, useState, useEffect, useCallback } from 'react';
import { MainLayout } from '../../layout/MainLayout';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  fetchAutomations,
  createAutomation,
  updateAutomation,
  deleteAutomation,
  fetchAutomationExecutions,
  fetchAutomationUsageStats,
  type Automation,
  type AutomationExecution,
  type AutomationUsageStats,
} from '../../api/automations';
import {
  fetchIntegrations,
  fetchAdapters,
  type IntegrationConnectionDto,
  type IntegrationAdapterDto,
} from '../../api/integrations';
import { getActionLabel, getTriggerLabel } from './automationLabels';
import { BUILT_IN_INTEGRATIONS, ROADMAP_INTEGRATIONS } from './integrationsCatalog';

type TabId = 'automations' | 'history' | 'integrations' | 'usage';

function executionActionSummary(row: AutomationExecution, t: (k: string, o?: object) => string) {
  const res = row.executionResult;
  if (!Array.isArray(res)) return '—';
  const total = res.length;
  const ok = res.filter((x: any) => x?.success).length;
  return t('crm.automations.panel.history.actionsCount', { ok, total });
}

export const AutomationsPage: React.FC = () => {
  const { t } = useTranslation();
  const [automations, setAutomations] = useState<Automation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive'>('all');
  const [activeTab, setActiveTab] = useState<TabId>('automations');

  const [executions, setExecutions] = useState<AutomationExecution[]>([]);
  const [execLoading, setExecLoading] = useState(false);
  const [execSearch, setExecSearch] = useState('');
  const [execStatus, setExecStatus] = useState<string>('');

  const [usage, setUsage] = useState<AutomationUsageStats | null>(null);
  const [usageLoading, setUsageLoading] = useState(false);
  const [usageDays, setUsageDays] = useState(30);

  const [connections, setConnections] = useState<IntegrationConnectionDto[]>([]);
  const [adapters, setAdapters] = useState<IntegrationAdapterDto[]>([]);
  const [intLoading, setIntLoading] = useState(false);
  const [intError, setIntError] = useState<string | null>(null);

  const navigate = useNavigate();

  const loadAutomations = useCallback(() => {
    setLoading(true);
    setError(null);
    return fetchAutomations()
      .then(setAutomations)
      .catch((e) => {
        console.error(e);
        setError(e.message || t('crm.automations.list.errors.loadFailed'));
      })
      .finally(() => setLoading(false));
  }, [t]);

  useEffect(() => {
    void loadAutomations();
  }, [loadAutomations]);

  useEffect(() => {
    if (activeTab !== 'history') return;
    let alive = true;
    setExecLoading(true);
    fetchAutomationExecutions(undefined, 200, execStatus || undefined)
      .then((rows) => {
        if (alive) setExecutions(rows);
      })
      .catch((e) => {
        console.error(e);
        if (alive) setError(e.message || t('crm.automations.list.errors.loadFailed'));
      })
      .finally(() => {
        if (alive) setExecLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [activeTab, execStatus, t]);

  useEffect(() => {
    if (activeTab !== 'usage') return;
    let alive = true;
    setUsageLoading(true);
    fetchAutomationUsageStats(usageDays)
      .then((u) => {
        if (alive) setUsage(u);
      })
      .catch((e) => {
        console.error(e);
        if (alive) setError(e.message || t('crm.automations.list.errors.loadFailed'));
      })
      .finally(() => {
        if (alive) setUsageLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [activeTab, usageDays, t]);

  useEffect(() => {
    if (activeTab !== 'integrations') return;
    let alive = true;
    setIntLoading(true);
    setIntError(null);
    Promise.all([fetchIntegrations(), fetchAdapters()])
      .then(([c, a]) => {
        if (!alive) return;
        setConnections(c);
        setAdapters(a);
      })
      .catch((e) => {
        console.error(e);
        if (alive) setIntError(e.message || t('crm.automations.panel.integrations.loadError'));
      })
      .finally(() => {
        if (alive) setIntLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [activeTab, t]);

  const handleCreate = () => navigate('/app/automations/new');
  const handleOpen = (id: string) => navigate(`/app/automations/${id}`);

  const handleToggle = async (automation: Automation) => {
    const next = !automation.isActive;
    setAutomations((prev) =>
      prev.map((item) => (item.id === automation.id ? { ...item, isActive: next } : item)),
    );
    try {
      await updateAutomation(automation.id, { isActive: next });
    } catch (err: any) {
      console.error(err);
      setAutomations((prev) =>
        prev.map((item) =>
          item.id === automation.id ? { ...item, isActive: automation.isActive } : item,
        ),
      );
    }
  };

  const handleArchive = async (automation: Automation) => {
    if (!automation.isActive) return;
    await handleToggle(automation);
  };

  const handleDuplicate = async (automation: Automation) => {
    try {
      const created = await createAutomation({
        name: `${automation.name} ${t('crm.automations.panel.copySuffix')}`,
        description: automation.description ?? undefined,
        triggerEvent: automation.triggerEvent,
        conditions: automation.conditions ?? undefined,
        actions: automation.actions,
        isActive: false,
      });
      setAutomations((prev) => [created, ...prev]);
    } catch (err: any) {
      console.error(err);
      setError(err.message || t('crm.automations.list.errors.loadFailed'));
    }
  };

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm(t('crm.automations.list.deleteConfirm'))) return;
    try {
      await deleteAutomation(id);
      setAutomations((prev) => prev.filter((a) => a.id !== id));
    } catch (err: any) {
      alert(err.message || t('crm.automations.list.errors.deleteFailed'));
    }
  };

  const filtered = useMemo(() => {
    const statusFiltered =
      statusFilter === 'all'
        ? automations
        : automations.filter((item) =>
            statusFilter === 'active' ? item.isActive : !item.isActive,
          );
    const query = search.trim().toLowerCase();
    if (!query) return statusFiltered;
    return statusFiltered.filter((item) => {
      const hay = [
        item.name,
        item.description ?? '',
        getTriggerLabel(item.triggerEvent),
        ...item.actions.map((a) => getActionLabel(a.type)),
      ]
        .join(' ')
        .toLowerCase();
      return hay.includes(query);
    });
  }, [automations, search, statusFilter]);

  const filteredExecutions = useMemo(() => {
    const q = execSearch.trim().toLowerCase();
    if (!q) return executions;
    return executions.filter((row) => {
      const name = row.automation?.name || '';
      const blob = [
        name,
        row.triggerEvent,
        row.status,
        row.errorMessage || '',
        row.entityType || '',
        row.entityId || '',
      ]
        .join(' ')
        .toLowerCase();
      return blob.includes(q);
    });
  }, [executions, execSearch]);

  const toolbarPlaceholder =
    activeTab === 'history'
      ? t('crm.automations.panel.history.searchPlaceholder')
      : activeTab === 'integrations'
        ? t('crm.automations.panel.integrations.searchPlaceholder')
        : t('crm.automations.panel.searchPlaceholder');

  const searchValue =
    activeTab === 'history' ? execSearch : activeTab === 'automations' ? search : '';
  const setSearchValue =
    activeTab === 'history'
      ? setExecSearch
      : activeTab === 'automations'
        ? setSearch
        : () => {};

  return (
    <MainLayout>
      <div className="space-y-4">
        <section className="rounded-3xl border border-slate-200 bg-white p-5">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <div className="text-[11px] uppercase tracking-[0.25em] text-slate-400">
                {t('crm.automations.panel.kicker')}
              </div>
              <h1 className="text-lg font-semibold text-slate-900">
                {t('crm.automations.list.title')}
              </h1>
              <div className="text-[12px] text-slate-500">
                {t('crm.automations.list.subtitle')}
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={handleCreate}
                className="px-3 py-1.5 text-xs rounded-xl bg-[#222222] text-white font-semibold hover:bg-black transition-colors"
              >
                {t('crm.automations.list.create')}
