import { Injectable } from '@nestjs/common';
import axios from 'axios';

/**
 * Microsoft Teams / Office 365 Incoming Webhook (MessageCard)
 * @see https://learn.microsoft.com/microsoftteams/platform/webhooks-and-connectors/how-to/connectors-using
 */
@Injectable()
export class TeamsWebhookService {
  async postConnectorCard(
    webhookUrl: string,
    title: string,
    text: string,
  ): Promise<{ status: number; body: string }> {
    const url = webhookUrl.trim();
    if (!url.startsWith('https://')) {
      throw new Error('Teams webhook URL must use HTTPS');
    }
    if (
      !url.includes('webhook.office.com') &&
      !url.includes('outlook.office.com/webhook')
    ) {
      throw new Error(
        'Ожидается URL Incoming Webhook Teams (webhook.office.com или outlook.office.com/webhook)',
      );
    }

    const payload = {
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: '0076D7',
      summary: title,
      sections: [
        {
          activityTitle: title,
          markdown: true,
          text,
        },
      ],
    };

    const res = await axios.post(url, payload, {
      headers: { 'Content-Type': 'application/json' },
      timeout: 15000,
      validateStatus: () => true,
    });

    const body = typeof res.data === 'string' ? res.data : JSON.stringify(res.data);

    if (res.status < 200 || res.status >= 300) {
      throw new Error(`Teams webhook HTTP ${res.status}: ${body.slice(0, 500)}`);
    }

    if (body && body.toLowerCase().includes('error')) {
      throw new Error(`Teams ответил ошибкой: ${body.slice(0, 500)}`);
    }

    return { status: res.status, body };
  }
}

import { Injectable } from '@nestjs/common';
import axios from 'axios';

/** Zapier Catch Hook (hooks.zapier.com) — POST JSON */
@Injectable()
export class ZapierHookService {
  async postCatchHook(
    webhookUrl: string,
    payload: Record<string, unknown>,
  ): Promise<{ status: number; body: string }> {
    const url = webhookUrl.trim();
    if (!url.startsWith('https://')) {
      throw new Error('Zapier hook URL must use HTTPS');
    }
    if (!url.includes('hooks.zapier.com')) {
      throw new Error('Ожидается Zapier Catch Hook (домен hooks.zapier.com)');
    }

    const res = await axios.post(url, payload, {
      headers: { 'Content-Type': 'application/json' },
      timeout: 15000,
      validateStatus: () => true,
    });

    const body = typeof res.data === 'string' ? res.data : JSON.stringify(res.data);

    if (res.status < 200 || res.status >= 300) {
      throw new Error(`Zapier HTTP ${res.status}: ${body.slice(0, 500)}`);
    }

    return { status: res.status, body };
  }
}

import { Injectable } from '@nestjs/common';
import axios from 'axios';

const GRAPH_VERSION = process.env.WHATSAPP_GRAPH_API_VERSION || 'v21.0';

/**
 * WhatsApp Cloud API — текстовое сообщение
 * @see https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages
 */
@Injectable()
export class WhatsappCloudService {
  normalizeE164(to: string): string {
    const digits = String(to || '').replace(/\D/g, '');
    return digits;
  }

  async sendTextMessage(params: {
    phoneNumberId: string;
    accessToken: string;
    to: string;
    body: string;
  }): Promise<{ messageId?: string }> {
    const { phoneNumberId, accessToken, to, body } = params;
    const toDigits = this.normalizeE164(to);
    if (!toDigits) {
      throw new Error('WhatsApp: укажите номер получателя (to) в формате E.164 без + или с +');
    }
    if (!phoneNumberId?.trim()) {
      throw new Error('WhatsApp: не указан Phone number ID');
    }
    if (!accessToken?.trim()) {
      throw new Error('WhatsApp: не указан access token');
    }

    const url = `https://graph.facebook.com/${GRAPH_VERSION}/${phoneNumberId.trim()}/messages`;

    const res = await axios.post(
      url,
      {
        messaging_product: 'whatsapp',
        to: toDigits,
        type: 'text',
        text: { body: body.slice(0, 4096) },
      },
      {
        headers: {
          Authorization: `Bearer ${accessToken.trim()}`,
          'Content-Type': 'application/json',
        },
        timeout: 20000,
        validateStatus: () => true,
      },
    );

    const data = res.data as { error?: { message?: string }; messages?: { id?: string }[] };
    if (res.status < 200 || res.status >= 300 || data?.error) {
      const msg = data?.error?.message || JSON.stringify(data).slice(0, 500);
      throw new Error(`WhatsApp API ${res.status}: ${msg}`);
    }

    const messageId = data?.messages?.[0]?.id;
    return { messageId };
  }

  /** Лёгкая проверка токена (без отправки сообщения) */
  async debugToken(accessToken: string): Promise<boolean> {
    const res = await axios.get(
      `https://graph.facebook.com/${GRAPH_VERSION}/debug_token`,
      {
        params: { input_token: accessToken.trim(), access_token: accessToken.trim() },
        timeout: 10000,
        validateStatus: () => true,
      },
    );
    return res.status >= 200 && res.status < 300;
  }
}

