  async getGoogleCalendarCredentialsForConnection(
    tenantId: string,
    connectionId: string,
  ): Promise<{ accessToken: string; calendarId: string } | null> {
    const entity = await this.repo.findOne({
      where: { id: connectionId, tenantId, isDeleted: false } as any,
    });
    if (!entity || entity.kind !== 'third_party_link' || !entity.configJson) {
      return null;
    }
    let cfg: {
      catalogId?: string;
      apiToken?: string;
      accountEmail?: string;
      calendarId?: string;
    };
    try {
      cfg = JSON.parse(entity.configJson) as {
        catalogId?: string;
        apiToken?: string;
        accountEmail?: string;
        calendarId?: string;
      };
    } catch {
      return null;
    }
    if (cfg.catalogId !== 'google_calendar') return null;
    const accessToken = typeof cfg.apiToken === 'string' ? cfg.apiToken.trim() : '';
    const fromField =
      (typeof cfg.calendarId === 'string' ? cfg.calendarId.trim() : '') ||
      (typeof cfg.accountEmail === 'string' ? cfg.accountEmail.trim() : '');
    const calendarId = fromField.length > 0 ? fromField : 'primary';
    if (!accessToken) return null;
    return { accessToken, calendarId };
  }

  async createGoogleCalendarEventRaw(
    accessToken: string,
    calendarId: string,
    params: {
      summary: string;
      description?: string;
      startIso: string;
      endIso: string;
      timeZone: string;
    },
  ): Promise<void> {
    await this.googleCalendar.insertEvent({
      accessToken,
      calendarId,
      summary: params.summary,
      description: params.description,
      startIso: params.startIso,
      endIso: params.endIso,
      timeZone: params.timeZone,
    });
  }
}

