import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, ILike } from 'typeorm';

import { IntegrationConnection } from '../integration-connection.entity';
import { Lead } from '../../leads/lead.entity';
import { LeadsService } from '../../leads/leads.service';
import { NotesService } from '../../notes/notes.service';
import { EntityType, NoteType } from '../../notes/dto/create-note.dto';

type HttpLeadCfg = {
  catalogId?: string;
  inboundSecret?: string;
};

function parseCfg(entity: IntegrationConnection): HttpLeadCfg | null {
  if (!entity.configJson) return null;
  try {
    return JSON.parse(entity.configJson) as HttpLeadCfg;
  } catch {
    return null;
  }
}

function asRecord(v: unknown): Record<string, unknown> {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v as Record<string, unknown>;
  }
  return {};
}

function pickString(obj: Record<string, unknown>, keys: string[]): string {
  for (const k of keys) {
    const v = obj[k];
    if (v == null) continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}

@Injectable()
export class InboundLeadWebhookService {
  private readonly log = new Logger(InboundLeadWebhookService.name);

  constructor(
    @InjectRepository(IntegrationConnection)
    private readonly integrationRepo: Repository<IntegrationConnection>,
    @InjectRepository(Lead)
    private readonly leadRepo: Repository<Lead>,
    private readonly leadsService: LeadsService,
    private readonly notesService: NotesService,
  ) {}

  extractProvidedSecret(headers: Record<string, string | string[] | undefined>): string {
    const auth = headers['authorization'];
    if (typeof auth === 'string' && auth.toLowerCase().startsWith('bearer ')) {
      return auth.slice(7).trim();
    }
    const x = headers['x-lumiva-secret'];
    return typeof x === 'string' ? x.trim() : '';
  }

  async loadHttpLeadConnection(
    connectionId: string,
  ): Promise<{ entity: IntegrationConnection; cfg: HttpLeadCfg } | null> {
    const entity = await this.integrationRepo.findOne({
      where: { id: connectionId, isDeleted: false, isEnabled: true } as any,
    });
    if (!entity || entity.kind !== 'third_party_link') return null;
    const cfg = parseCfg(entity);
    if (!cfg || cfg.catalogId !== 'http_lead') return null;
    return { entity, cfg };
  }

  verifySecretOrThrow(
    cfg: HttpLeadCfg,
    provided: string,
  ): void {
    const expected = String(cfg.inboundSecret || '').trim();
    if (!expected || provided !== expected) {
      throw new Error('Secret mismatch');
    }
  }

  private normalizeDigits(phone: string): string {
    return String(phone || '').replace(/\D/g, '');
  }

  private async findLeadByPhoneDigits(
    tenantId: string,
    digits: string,
  ): Promise<Lead | null> {
    if (!digits) return null;
    return this.leadRepo
      .createQueryBuilder('l')
      .where('l.tenantId = :tenantId', { tenantId })
      .andWhere("regexp_replace(coalesce(l.phone, ''), '[^0-9]', '', 'g') = :digits", {
        digits,
      })
      .orderBy('l.updatedAt', 'DESC')
      .getOne();
  }

  private async findLeadByEmail(tenantId: string, email: string): Promise<Lead | null> {
    const e = email.trim().toLowerCase();
    if (!e) return null;
    return this.leadRepo.findOne({
      where: { tenantId, email: ILike(e) },
      order: { updatedAt: 'DESC' },
    });
  }

  private flattenPayload(body: unknown): Record<string, unknown> {
    const root = asRecord(body);
    const nested = asRecord(root.data ?? root.payload ?? root.body ?? root.fields);
    return { ...root, ...nested };
  }

  private parseInboundFields(body: unknown): {
    name: string;
    phone: string;
    email: string;
    message: string;
    source: string;
  } {
    const o = this.flattenPayload(body);
    const first = pickString(o, ['first_name', 'firstName', 'firstname']);
    const last = pickString(o, ['last_name', 'lastName', 'lastname']);
    let name = pickString(o, ['name', 'full_name', 'fullname', 'contact_name', 'title', 'fio']);
    if (!name && (first || last)) {
      name = [first, last].filter(Boolean).join(' ').trim();
    }
    const phone = pickString(o, [
      'phone',
      'Phone',
      'tel',
      'mobile',
      'phone_number',
      'phoneNumber',
    ]);
    const email = pickString(o, ['email', 'Email', 'mail']);
    const message = pickString(o, [
      'message',
      'text',
      'body',
      'comment',
      'description',
      'details',
      'notes',
    ]);
    const source = pickString(o, ['source', 'utm_source', 'utmSource']) || 'http_inbound';
    return { name, phone, email, message, source };
  }

  async handleInbound(
    connectionId: string,
    headers: Record<string, string | string[] | undefined>,
    body: unknown,
  ): Promise<void> {
    const row = await this.loadHttpLeadConnection(connectionId);
    if (!row) {
      this.log.warn(`Inbound lead webhook: connection ${connectionId} not found or not http_lead`);
      return;
    }
    const { entity, cfg } = row;
    const tenantId = entity.tenantId;

    try {
      this.verifySecretOrThrow(cfg, this.extractProvidedSecret(headers));
    } catch {
      this.log.warn(`Inbound lead webhook: secret mismatch for ${connectionId}`);
      return;
    }

    const parsed = this.parseInboundFields(body);
    const digits = this.normalizeDigits(parsed.phone);

    let lead: Lead | null = null;
    if (digits) {
      lead = await this.findLeadByPhoneDigits(tenantId, digits);
    }
    if (!lead && parsed.email) {
      lead = await this.findLeadByEmail(tenantId, parsed.email);
    }

    const displayName =
      parsed.name ||
      (parsed.email ? parsed.email.split('@')[0] : '') ||
      (digits ? `+${digits}` : 'Входящий лид (HTTP)');

    if (!lead) {
      const phone =
        parsed.phone && String(parsed.phone).trim().startsWith('+')
          ? String(parsed.phone).trim()
          : digits
            ? `+${digits}`
            : undefined;
      lead = await this.leadsService.createForTenant(tenantId, {
        name: displayName,
        ...(phone ? { phone } : {}),
        ...(parsed.email ? { email: parsed.email } : {}),
        source: parsed.source.slice(0, 64),
        status: 'new',
        meta: {
          inboundConnectionId: connectionId,
          inboundChannel: 'http_lead',
        },
      });
    }

    const jsonPreview = (() => {
      try {
        const s = JSON.stringify(body, null, 0);
        return s.length > 4000 ? `${s.slice(0, 4000)}…` : s;
      } catch {
        return String(body);
      }
    })();

    const lines = [
      'Входящий лид по HTTP',
      `Подключение: ${entity.name} (${connectionId.slice(0, 8)}…)`,
      parsed.name ? `Имя: ${parsed.name}` : null,
      parsed.phone ? `Телефон: ${parsed.phone}` : null,
      parsed.email ? `Email: ${parsed.email}` : null,
      '',
      parsed.message || '(текст сообщения не передан)',
      '',
      '--- JSON ---',
      jsonPreview,
    ]
      .filter((x) => x != null)
      .join('\n');

    await this.notesService.create(
      tenantId,
      {
        entityType: EntityType.LEAD,
        entityId: lead.id,
        content: lines,
        title: 'HTTP · входящий лид',
        type: NoteType.NOTE,
        metadata: {
          channel: 'http_lead_inbound',
          connectionId,
        },
      },
      undefined,
      'HTTP Lead',
    );
  }
}

import { Body, Controller, Logger, Param, Post, Headers } from '@nestjs/common';
import { InboundLeadWebhookService } from './inbound-lead-webhook.service';

/**
 * Приём лидов из внешних систем (Zapier, Make, формы) без JWT.
 * POST /v1/webhooks/inbound-leads/:connectionId
 * Заголовок: X-Lumiva-Secret: <inboundSecret> или Authorization: Bearer <inboundSecret>
 */
@Controller('webhooks/inbound-leads')
export class InboundLeadWebhookController {
  private readonly log = new Logger(InboundLeadWebhookController.name);

  constructor(private readonly svc: InboundLeadWebhookService) {}

  @Post(':connectionId')
  async receive(
    @Param('connectionId') connectionId: string,
    @Headers() headers: Record<string, string | string[] | undefined>,
    @Body() body: unknown,
  ): Promise<{ ok: true }> {
    try {
      await this.svc.handleInbound(connectionId, headers, body);
    } catch (e) {
      this.log.error((e as Error).stack || (e as Error).message);
    }
    return { ok: true };
  }
}

