import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { randomUUID } from 'crypto';

import { IntegrationConnection } from '../integration-connection.entity';
import { Lead } from '../../leads/lead.entity';
import { Sale, type SaleStatus } from '../../sales/sale.entity';
import { LeadsService } from '../../leads/leads.service';
import { NotesService } from '../../notes/notes.service';
import { EntityType, NoteType } from '../../notes/dto/create-note.dto';

type HttpSaleCfg = {
  catalogId?: string;
  inboundSecret?: string;
};

function parseCfg(entity: IntegrationConnection): HttpSaleCfg | null {
  if (!entity.configJson) return null;
  try {
    return JSON.parse(entity.configJson) as HttpSaleCfg;
  } catch {
    return null;
  }
}

function asRecord(v: unknown): Record<string, unknown> {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v as Record<string, unknown>;
  }
  return {};
}

function pickString(obj: Record<string, unknown>, keys: string[]): string {
  for (const k of keys) {
    const v = obj[k];
    if (v == null) continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}

function pickNumber(obj: Record<string, unknown>, keys: string[]): number {
  for (const k of keys) {
    const v = obj[k];
    if (v == null) continue;
    const n = typeof v === 'number' ? v : Number(String(v).replace(',', '.'));
    if (!Number.isFinite(n)) continue;
    return n;
  }
  return 0;
}

function pickBool(obj: Record<string, unknown>, keys: string[]): boolean {
  for (const k of keys) {
    const v = obj[k];
    if (v === true) return true;
    if (v === false || v == null) continue;
    const s = String(v).trim().toLowerCase();
    if (s === '1' || s === 'true' || s === 'yes') return true;
  }
  return false;
}

@Injectable()
export class InboundSaleWebhookService {
  private readonly log = new Logger(InboundSaleWebhookService.name);

  constructor(
    @InjectRepository(IntegrationConnection)
    private readonly integrationRepo: Repository<IntegrationConnection>,
    @InjectRepository(Lead)
    private readonly leadRepo: Repository<Lead>,
    @InjectRepository(Sale)
    private readonly saleRepo: Repository<Sale>,
    private readonly leadsService: LeadsService,
    private readonly notesService: NotesService,
  ) {}

  extractProvidedSecret(headers: Record<string, string | string[] | undefined>): string {
    const auth = headers['authorization'];
    if (typeof auth === 'string' && auth.toLowerCase().startsWith('bearer ')) {
      return auth.slice(7).trim();
    }
    const x = headers['x-lumiva-secret'];
    return typeof x === 'string' ? x.trim() : '';
  }

  async loadHttpSaleConnection(
    connectionId: string,
  ): Promise<{ entity: IntegrationConnection; cfg: HttpSaleCfg } | null> {
    const entity = await this.integrationRepo.findOne({
      where: { id: connectionId, isDeleted: false, isEnabled: true } as any,
    });
    if (!entity || entity.kind !== 'third_party_link') return null;
    const cfg = parseCfg(entity);
    if (!cfg || cfg.catalogId !== 'http_sale') return null;
    return { entity, cfg };
  }

  verifySecretOrThrow(cfg: HttpSaleCfg, provided: string): void {
    const expected = String(cfg.inboundSecret || '').trim();
    if (!expected || provided !== expected) {
      throw new Error('Secret mismatch');
    }
  }

  private normalizeDigits(phone: string): string {
    return String(phone || '').replace(/\D/g, '');
  }

  private async findLeadByPhoneDigits(
    tenantId: string,
    digits: string,
  ): Promise<Lead | null> {
    if (!digits) return null;
    return this.leadRepo
      .createQueryBuilder('l')
      .where('l.tenantId = :tenantId', { tenantId })
      .andWhere("regexp_replace(coalesce(l.phone, ''), '[^0-9]', '', 'g') = :digits", {
        digits,
      })
      .orderBy('l.updatedAt', 'DESC')
      .getOne();
  }

  private async findLeadByEmail(tenantId: string, email: string): Promise<Lead | null> {
    const e = email.trim();
    if (!e) return null;
    return this.leadRepo
      .createQueryBuilder('l')
      .where('l.tenantId = :tenantId', { tenantId })
      .andWhere('LOWER(TRIM(l.email)) = LOWER(TRIM(:email))', { email: e })
      .orderBy('l.updatedAt', 'DESC')
      .getOne();
  }

  private flattenPayload(body: unknown): Record<string, unknown> {
    const root = asRecord(body);
    const nested = asRecord(root.data ?? root.payload ?? root.body ?? root.fields);
    return { ...root, ...nested };
  }

  private mapInboundStatus(raw: string): SaleStatus {
    const s = raw.toLowerCase();
    if (
      ['pending', 'processing', 'on-hold', 'on_hold', 'awaiting_payment'].includes(s)
    ) {
      return 'pending';
    }
    if (
      [
        'confirmed',
        'completed',
        'paid',
        'success',
        'succeeded',
        'done',
        'win',
        'won',
      ].includes(s)
    ) {
      return 'confirmed';
    }
    if (['cancelled', 'canceled', 'failed', 'void'].includes(s)) {
      return 'cancelled';
    }
    if (['refunded', 'refund'].includes(s)) {
      return 'refunded';
    }
    if (['new'].includes(s)) {
      return 'new';
    }
    return 'other';
  }

  private parseLeadHints(o: Record<string, unknown>) {
    const first = pickString(o, ['first_name', 'firstName', 'firstname']);
    const last = pickString(o, ['last_name', 'lastName', 'lastname']);
    let name = pickString(o, [
      'name',
      'full_name',
      'fullname',
      'contact_name',
      'customer_name',
      'client_name',
      'guestName',
      'guest_name',
    ]);
    if (!name && (first || last)) {
      name = [first, last].filter(Boolean).join(' ').trim();
    }
    const phone = pickString(o, [
      'phone',
      'Phone',
      'tel',
      'mobile',
      'phone_number',
      'phoneNumber',
    ]);
    const email = pickString(o, ['email', 'Email', 'mail']);
    const source = pickString(o, ['source', 'utm_source', 'utmSource']) || 'http_sale_inbound';
    return { name, phone, email, source };
  }

  private parseSaleFields(body: unknown): {
    amount: number;
    currency: string;
    status: SaleStatus;
    externalId: string;
    externalOrderNo: string;
    guestName: string | null;
    saleDate: Date;
    notes: string | null;
    managerName: string | null;
    hotel: string | null;
    market: string | null;
    leadId: string | null;
    createLead: boolean;
  } {
    const o = this.flattenPayload(body);
    const amount = pickNumber(o, ['amount', 'total', 'sum', 'price', 'value']);
    const currency =
      pickString(o, ['currency', 'curr', 'currency_code', 'currencyCode']) || 'EUR';
    const statusRaw = pickString(o, ['status', 'sale_status', 'saleStatus', 'payment_status']);
    const status = statusRaw ? this.mapInboundStatus(statusRaw) : 'confirmed';
    let externalId = pickString(o, [
      'externalId',
      'external_id',
      'order_id',
      'orderId',
      'id',
      'transaction_id',
      'transactionId',
    ]);
    if (!externalId) {
      externalId = `lumiva-http-${randomUUID()}`;
    }
    const externalOrderNo = pickString(o, [
      'externalOrderNo',
      'external_order_no',
      'order_number',
      'orderNumber',
      'number',
    ]);
    const hints = this.parseLeadHints(o);
    const guestName =
      hints.name ||
      pickString(o, ['guestName', 'guest_name', 'client', 'customer']) ||
      null;
    const saleDateStr = pickString(o, [
      'saleDate',
      'sale_date',
      'date',
      'purchased_at',
      'created_at',
      'paid_at',
    ]);
    const saleDate = saleDateStr ? new Date(saleDateStr) : new Date();
    const notes =
      pickString(o, ['notes', 'note', 'description', 'message', 'comment', 'details']) ||
      null;
    const managerName = pickString(o, ['managerName', 'manager_name', 'manager']) || null;
    const hotel = pickString(o, ['product', 'product_name', 'sku', 'hotel', 'item']) || null;
    const market = pickString(o, ['market', 'country', 'region']) || null;
    const leadIdRaw = pickString(o, ['leadId', 'lead_id']);
    const createLead = pickBool(o, ['createLead', 'create_lead', 'with_lead']);
    return {
      amount,
      currency: currency.slice(0, 8).toUpperCase() || 'EUR',
      status,
      externalId: externalId.slice(0, 128),
      externalOrderNo: externalOrderNo.slice(0, 255),
      guestName: guestName ? guestName.slice(0, 255) : null,
      saleDate: Number.isNaN(saleDate.getTime()) ? new Date() : saleDate,
      notes: notes ? notes.slice(0, 8000) : null,
      managerName: managerName ? managerName.slice(0, 255) : null,
      hotel: hotel ? hotel.slice(0, 255) : null,
      market: market ? market.slice(0, 64) : null,
      leadId: leadIdRaw || null,
      createLead,
    };
  }

  private async resolveLeadId(
    tenantId: string,
    connectionId: string,
    parsed: ReturnType<InboundSaleWebhookService['parseSaleFields']>,
    hints: ReturnType<InboundSaleWebhookService['parseLeadHints']>,
  ): Promise<string | null> {
    if (parsed.leadId) {
      const found = await this.leadRepo.findOne({
        where: { id: parsed.leadId, tenantId } as any,
      });
      return found?.id ?? null;
    }
    const digits = this.normalizeDigits(hints.phone);
    let lead = digits ? await this.findLeadByPhoneDigits(tenantId, digits) : null;
    if (!lead && hints.email) {
      lead = await this.findLeadByEmail(tenantId, hints.email);
    }
    if (lead) return lead.id;
    if (!parsed.createLead) return null;

    const displayName =
      hints.name ||
      (hints.email ? hints.email.split('@')[0] : '') ||
      (digits ? `+${digits}` : 'Клиент (HTTP → продажа)');
    const phone =
      hints.phone && String(hints.phone).trim().startsWith('+')
        ? String(hints.phone).trim()
        : digits
          ? `+${digits}`
          : undefined;
    const created = await this.leadsService.createForTenant(tenantId, {
      name: displayName,
      ...(phone ? { phone } : {}),
      ...(hints.email ? { email: hints.email } : {}),
      source: hints.source.slice(0, 64),
      status: 'new',
      meta: {
        inboundConnectionId: connectionId,
        inboundChannel: 'http_sale',
      },
    });
    return created.id;
  }

  async handleInbound(
    connectionId: string,
    headers: Record<string, string | string[] | undefined>,
    body: unknown,
  ): Promise<void> {
    const row = await this.loadHttpSaleConnection(connectionId);
    if (!row) {
      this.log.warn(`Inbound sale webhook: connection ${connectionId} not found or not http_sale`);
      return;
    }
    const { entity, cfg } = row;
    const tenantId = entity.tenantId;

    try {
      this.verifySecretOrThrow(cfg, this.extractProvidedSecret(headers));
    } catch {
      this.log.warn(`Inbound sale webhook: secret mismatch for ${connectionId}`);
      return;
    }

    const parsed = this.parseSaleFields(body);
    const hints = this.parseLeadHints(this.flattenPayload(body));
    const leadId = await this.resolveLeadId(tenantId, connectionId, parsed, hints);

    const where: Record<string, unknown> = {
      tenantId,
      externalId: parsed.externalId,
    };
    if (entity.channelId) {
      where.channelId = entity.channelId;
    }

    const existing = await this.saleRepo.findOne({ where: where as any });

    const baseSale: Partial<Sale> = {
      tenantId,
      channelId: entity.channelId ?? null,
      leadId,
      externalId: parsed.externalId,
      externalOrderNo: parsed.externalOrderNo || null,
      saleDate: parsed.saleDate,
      guestName: parsed.guestName,
      amount: Math.max(0, parsed.amount),
      currency: parsed.currency,
      status: parsed.status,
      notes: parsed.notes,
      managerName: parsed.managerName,
      hotel: parsed.hotel,
      market: parsed.market,
      rawPayload: body,
    };

    let sale: Sale;
    if (existing) {
      this.saleRepo.merge(existing, baseSale);
      sale = await this.saleRepo.save(existing);
    } else {
      sale = await this.saleRepo.save(this.saleRepo.create(baseSale));
    }

    const jsonPreview = (() => {
      try {
        const s = JSON.stringify(body, null, 0);
        return s.length > 4000 ? `${s.slice(0, 4000)}…` : s;
      } catch {
        return String(body);
      }
    })();

    const lines = [
      'Входящая продажа по HTTP',
      `Подключение: ${entity.name} (${connectionId.slice(0, 8)}…)`,
      `Сумма: ${parsed.amount} ${parsed.currency}`,
      `Статус: ${parsed.status}`,
      parsed.externalOrderNo ? `Номер заказа: ${parsed.externalOrderNo}` : null,
      '',
      '--- JSON ---',
      jsonPreview,
    ]
      .filter((x) => x != null)
      .join('\n');

    await this.notesService.create(
      tenantId,
      {
        entityType: EntityType.SALE,
        entityId: sale.id,
        content: lines,
        title: 'HTTP · входящая продажа',
        type: NoteType.NOTE,
        metadata: {
          channel: 'http_sale_inbound',
          connectionId,
        },
      },
      undefined,
      'HTTP Sale',
    );
  }
}

import { Body, Controller, Logger, Param, Post, Headers } from '@nestjs/common';
import { InboundSaleWebhookService } from './inbound-sale-webhook.service';

/**
 * Приём продаж из внешних систем (Zapier, Make, платёжные вебхуки) без JWT.
 * POST /v1/webhooks/inbound-sales/:connectionId
 * Заголовок: X-Lumiva-Secret или Authorization: Bearer (как у HTTP → лид).
 */
@Controller('webhooks/inbound-sales')
export class InboundSaleWebhookController {
  private readonly log = new Logger(InboundSaleWebhookController.name);

  constructor(private readonly svc: InboundSaleWebhookService) {}

  @Post(':connectionId')
  async receive(
    @Param('connectionId') connectionId: string,
    @Headers() headers: Record<string, string | string[] | undefined>,
    @Body() body: unknown,
  ): Promise<{ ok: true }> {
    try {
      await this.svc.handleInbound(connectionId, headers, body);
    } catch (e) {
      this.log.error((e as Error).stack || (e as Error).message);
    }
