import React, { useMemo } from 'react';

/** Демо-значения, чтобы в превью не торчали сырые {{...}} */
const PREVIEW_PLACEHOLDERS: Record<string, string> = {
  'lead.name': 'Иван Петров',
  'lead.email': 'ivan@example.com',
  'lead.phone': '+7 900 000-00-00',
  'lead.status': 'Новый',
