import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { MainLayout } from '../../layout/MainLayout';
import {
  fetchIntegrations,
  fetchIntegrationHubCatalog,
  syncIntegration,
  testIntegration,
  type IntegrationConnectionDto,
  type IntegrationHubCatalogEntry,
} from '../../api/integrations';
import { IntegrationBrandIcon } from '../automations/IntegrationBrandIcon';
import { integrationCatalogName } from '../automations/integrationsCatalog';

function lifecycleBadgeClass(lifecycle: IntegrationHubCatalogEntry['lifecycle']): string {
  switch (lifecycle) {
    case 'live':
      return 'bg-emerald-50 text-emerald-900 border-emerald-200';
    case 'beta':
      return 'bg-sky-50 text-sky-900 border-sky-200';
    case 'planned':
      return 'bg-slate-100 text-slate-700 border-slate-200';
    default:
      return 'bg-amber-50 text-amber-900 border-amber-200';
  }
}

function connectionMatchesCatalogId(
  c: IntegrationConnectionDto,
  catalogId: string,
): boolean {
  return c.kind === 'third_party_link' && c.linkCatalogId === catalogId;
}

export const IntegrationsHubPage: React.FC = () => {
  const { t } = useTranslation();
  const [catalog, setCatalog] = useState<IntegrationHubCatalogEntry[]>([]);
  const [connections, setConnections] = useState<IntegrationConnectionDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [testingId, setTestingId] = useState<string | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [actionMsg, setActionMsg] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [cat, conn] = await Promise.all([
        fetchIntegrationHubCatalog(),
        fetchIntegrations(),
      ]);
      setCatalog(Array.isArray(cat) ? cat : []);
      setConnections(Array.isArray(conn) ? conn : []);
    } catch (e) {
      setError(
        (e as Error)?.message || t('crm.integrationsHub.loadError'),
      );
    } finally {
      setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    void load();
  }, [load]);

  const catalogIds = useMemo(() => new Set(catalog.map((e) => e.id)), [catalog]);

  const hubConnections = useMemo(
    () =>
      connections.filter(
        (c) =>
          c.kind === 'third_party_link' &&
          c.linkCatalogId &&
          catalogIds.has(c.linkCatalogId),
      ),
    [connections, catalogIds],
  );

  const otherConnections = useMemo(
    () => connections.filter((c) => !hubConnections.some((h) => h.id === c.id)),
    [connections, hubConnections],
  );

  const countForCatalogId = useCallback(
    (id: string) => connections.filter((c) => connectionMatchesCatalogId(c, id)).length,
    [connections],
  );

  const capabilityChips = useCallback(
    (caps: IntegrationHubCatalogEntry['capabilities']) => {
      const items: { key: string; on: boolean }[] = [
        { key: 'outboundAutomation', on: caps.outboundAutomationActions },
        { key: 'inboundWebhook', on: caps.inboundWebhook },
        { key: 'oauthPlatform', on: caps.oauthPlatformSupported },
        { key: 'salesImport', on: caps.salesImport },
        { key: 'workspaceSync', on: caps.workspaceTableSync },
        { key: 'calendar', on: caps.calendarSync },
        { key: 'leadCapture', on: caps.leadCapture },
      ];
      return items.filter((x) => x.on);
    },
    [],
  );

  const handleTest = async (id: string) => {
    setTestingId(id);
    setActionMsg(null);
    try {
      const r = await testIntegration(id);
      setActionMsg(
        r.ok
          ? r.message || 'OK'
          : r.message || t('crm.integrationsHub.testFailed'),
      );
    } catch (e) {
      setActionMsg((e as Error).message);
    } finally {
      setTestingId(null);
    }
  };

  const handleSync = async (id: string) => {
    setSyncingId(id);
    setActionMsg(null);
    try {
      const r = await syncIntegration(id);
      setActionMsg(
        r.message ||
          t('crm.integrationsHub.syncDone', {
            ok: r.ok ? 'OK' : '—',
            created: r.created,
            updated: r.updated,
          }),
      );
      await load();
    } catch (e) {
      setActionMsg((e as Error).message);
    } finally {
      setSyncingId(null);
    }
  };

  const sortedCatalog = useMemo(() => {
    const order: Record<IntegrationHubCatalogEntry['lifecycle'], number> = {
      live: 0,
      beta: 1,
      planned: 2,
      in_development: 3,
    };
    return [...catalog].sort((a, b) => {
      const d = order[a.lifecycle] - order[b.lifecycle];
      return d !== 0 ? d : a.id.localeCompare(b.id);
    });
  }, [catalog]);

  return (
    <MainLayout>
      <div className="space-y-8">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <h1 className="text-lg font-semibold text-slate-900">
              {t('crm.integrationsHub.title')}
            </h1>
            <p className="text-xs text-slate-600 mt-1 max-w-3xl leading-relaxed">
              {t('crm.integrationsHub.subtitle')}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="rounded-full border border-slate-200 bg-white px-4 py-2 text-xs font-semibold text-slate-800 hover:bg-slate-50 disabled:opacity-50"
            >
              {t('crm.integrationsHub.refresh')}
            </button>
            <Link
              to="/automations?tab=integrations"
              className="inline-flex items-center justify-center rounded-full bg-[#222222] px-4 py-2 text-xs font-semibold text-white hover:opacity-90"
            >
              {t('crm.integrationsHub.openAutomationsIntegrations')}
            </Link>
          </div>
        </div>

        {actionMsg && (
          <div className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-800">
            {actionMsg}
          </div>
        )}

        {loading && (
          <p className="text-xs text-slate-500">{t('crm.automations.list.loading')}</p>
        )}
        {error && (
          <div className="rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-xs text-rose-800">
            {error}
          </div>
        )}

        {!loading && !error && (
          <>
            <section className="space-y-3">
              <div className="flex items-baseline justify-between gap-2">
                <h2 className="text-sm font-semibold text-slate-900">
                  {t('crm.integrationsHub.catalogHeading')}
                </h2>
                <p className="text-[10px] text-slate-500 max-w-md text-right leading-snug">
                  {t('crm.integrationsHub.openAutomationsIntegrationsHint')}
                </p>
              </div>
              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
                {sortedCatalog.map((entry) => {
                  const n = countForCatalogId(entry.id);
                  const caps = capabilityChips(entry.capabilities);
                  return (
                    <div
                      key={entry.id}
                      className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"
                    >
                      <div className="flex gap-3">
                        <IntegrationBrandIcon
                          catalogId={entry.id}
                          label={integrationCatalogName(entry.id, t)}
                          size={44}
                        />
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="text-sm font-semibold text-slate-900 truncate">
                              {integrationCatalogName(entry.id, t)}
                            </span>
                            <span
                              className={`text-[10px] font-semibold uppercase tracking-wide rounded-full border px-2 py-0.5 shrink-0 ${lifecycleBadgeClass(entry.lifecycle)}`}
                            >
                              {t(`crm.integrationsHub.lifecycle.${entry.lifecycle}`)}
                            </span>
                            {n > 0 ? (
                              <span className="text-[10px] font-semibold text-emerald-800 bg-emerald-50 border border-emerald-200 rounded-full px-2 py-0.5">
                                {t('crm.integrationsHub.connectedCount', { count: n })}
                              </span>
                            ) : null}
                          </div>
                          <div className="mt-2 text-[10px] text-slate-500 font-medium uppercase tracking-wide">
                            {t('crm.integrationsHub.modulesLabel')}
                          </div>
                          <div className="mt-1 flex flex-wrap gap-1">
                            {entry.modules.map((m) => (
                              <span
                                key={m}
                                className="rounded-md bg-slate-100 text-slate-700 px-2 py-0.5 text-[10px]"
                              >
                                {t(`crm.integrationsHub.module.${m}`)}
                              </span>
                            ))}
                          </div>
                          {caps.length > 0 ? (
                            <>
                              <div className="mt-2 text-[10px] text-slate-500 font-medium uppercase tracking-wide">
                                {t('crm.integrationsHub.capabilitiesLabel')}
                              </div>
                              <div className="mt-1 flex flex-wrap gap-1">
                                {caps.map(({ key }) => (
                                  <span
                                    key={key}
                                    className="rounded-md border border-slate-200 text-slate-700 px-2 py-0.5 text-[10px]"
                                  >
                                    {t(`crm.integrationsHub.cap.${key}`)}
                                  </span>
                                ))}
                              </div>
                            </>
                          ) : null}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>

            <section className="space-y-3">
              <h2 className="text-sm font-semibold text-slate-900">
                {t('crm.integrationsHub.connectionsHeading')}
              </h2>
              {connections.length === 0 ? (
                <p className="text-sm text-slate-500">
                  {t('crm.integrationsHub.connectionsEmpty')}
                </p>
              ) : (
                <div className="space-y-6">
                  {hubConnections.length > 0 && (
                    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                      {hubConnections.map((c) => (
                        <div
                          key={c.id}
                          className="rounded-2xl border border-slate-200 bg-slate-50/80 p-4 shadow-sm"
                        >
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex min-w-0 gap-2">
                              {c.linkCatalogId ? (
                                <IntegrationBrandIcon
                                  catalogId={c.linkCatalogId}
                                  label={c.name}
                                  size={40}
                                />
                              ) : null}
                              <div className="min-w-0">
                                <div className="text-sm font-semibold text-slate-900 truncate">
                                  {c.name}
                                </div>
                                {c.linkCatalogId ? (
                                  <div className="text-[10px] text-slate-500 mt-0.5">
                                    {integrationCatalogName(c.linkCatalogId, t)}
                                  </div>
                                ) : null}
                              </div>
                            </div>
                            <span
                              className={`shrink-0 text-[10px] font-semibold px-2 py-0.5 rounded-full border ${
                                c.isEnabled
                                  ? 'bg-emerald-50 text-emerald-800 border-emerald-200'
                                  : 'bg-slate-100 text-slate-500 border-slate-200'
                              }`}
                            >
                              {c.isEnabled
                                ? t('crm.automations.panel.integrations.statusLive')
                                : t('crm.automations.panel.integrations.statusOff')}
                            </span>
                          </div>
                          {c.lastError ? (
                            <p className="mt-2 text-[10px] text-rose-700 line-clamp-2">
                              {c.lastError}
                            </p>
                          ) : null}
                          <div className="mt-2 text-[10px] text-slate-600">
                            {t('crm.integrationsHub.lastSync')}:{' '}
                            {c.lastSyncAt
                              ? new Date(c.lastSyncAt).toLocaleString()
                              : t('crm.integrationsHub.never')}
                            {c.lastSyncStatus
                              ? ` · ${c.lastSyncStatus}`
                              : ''}
                          </div>
                          <div className="mt-3 flex flex-wrap gap-2">
                            <button
                              type="button"
                              disabled={testingId === c.id}
                              onClick={() => void handleTest(c.id)}
                              className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-[10px] font-semibold text-slate-800 hover:bg-slate-50 disabled:opacity-50"
                            >
                              {testingId === c.id
                                ? t('crm.integrationsHub.testing')
                                : t('crm.integrationsHub.test')}
                            </button>
                            <button
                              type="button"
                              disabled={syncingId === c.id}
                              onClick={() => void handleSync(c.id)}
