function matchesNavPath(pathname: string, navPath: string): boolean {
  const candidates = [navPath, toLegacyNavPath(navPath)].filter(
    (v, i, a) => a.indexOf(v) === i,
  );
  return candidates.some(
    (c) => pathname === c || pathname.startsWith(`${c}/`),
  );
}

