import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { integrationCatalogName } from '../../pages/automations/integrationsCatalog';
import {
  MarketingIntegrationsPanel,
  type MarketingIntegrationProviderKey,
} from '../../pages/marketing/MarketingIntegrationsPanel';

export type MarketingIntegrationSetupModalProps = {
  open: boolean;
  catalogId: string;
  provider: MarketingIntegrationProviderKey;
  onClose: () => void;
  onDataChanged?: () => void;
};

export const MarketingIntegrationSetupModal: React.FC<MarketingIntegrationSetupModalProps> = ({
  open,
  catalogId,
  provider,
  onClose,
  onDataChanged,
}) => {
  const { t } = useTranslation();

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open || typeof document === 'undefined') return null;

  const title = t('crm.integrationsHub.marketingModalTitle', {
    name: integrationCatalogName(catalogId, t),
  });

  return createPortal(
    <div
      className="fixed inset-0 z-[85] flex items-end justify-center bg-slate-900/50 p-3 sm:items-center sm:p-6"
      role="dialog"
      aria-modal
      aria-labelledby="marketing-setup-modal-title"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className="flex max-h-[min(92vh,900px)] w-full max-w-4xl flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl"
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className="flex shrink-0 items-start justify-between gap-3 border-b border-slate-100 bg-slate-50/90 px-4 py-3 sm:px-5">
          <div className="min-w-0">
            <h2
              id="marketing-setup-modal-title"
              className="text-sm font-semibold text-slate-900 sm:text-base"
            >
              {title}
            </h2>
            <p className="mt-1 text-[11px] leading-snug text-slate-600">
              {t('crm.integrationsHub.marketingModalSubtitle')}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="shrink-0 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 hover:bg-slate-50"
          >
            {t('crm.integrationsHub.marketingModalClose')}
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-3 py-4 sm:px-5 sm:py-5">
          <MarketingIntegrationsPanel
            key={`${catalogId}-${provider}`}
            variant="modal"
            initialProvider={provider}
            onMarketingDataChanged={onDataChanged}
          />
        </div>
      </div>
    </div>,
    document.body,
  );
};

