import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';

export type BlurBottomSheetProps = {
  open: boolean;
  onClose: () => void;
  /** Root of the sheet (not the backdrop) — stopPropagation on mousedown */
  children: React.ReactNode;
  /** Optional labelled-by for dialog */
  labelledBy?: string;
};

/**
 * Full-width bottom sheet with frosted glass panel and blurred dim backdrop.
 * Mobile-first; safe-area padding at the bottom.
 */
export const BlurBottomSheet: React.FC<BlurBottomSheetProps> = ({
  open,
  onClose,
  children,
  labelledBy,
}) => {
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener('keydown', onKey);
    };
  }, [open, onClose]);

  if (!open || typeof document === 'undefined') return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[85] flex flex-col justify-end bg-slate-950/45 backdrop-blur-[10px] sm:backdrop-blur-md"
      role="dialog"
      aria-modal
      aria-labelledby={labelledBy}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className="flex max-h-[min(92dvh,920px)] w-full flex-col overflow-hidden rounded-t-2xl border border-white/25 border-b-0 bg-white/82 shadow-[0_-24px_80px_rgba(15,23,42,0.28)] backdrop-blur-xl sm:rounded-t-3xl pb-[max(0.75rem,env(safe-area-inset-bottom))]"
        onMouseDown={(e) => e.stopPropagation()}
      >
        {children}
      </div>
    </div>,
    document.body,
  );
};

