import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';

export type BlurModalSize = 'sm' | 'md' | 'lg' | 'xl';

export type BlurModalProps = {
  open: boolean;
  onClose: () => void;
  children: React.ReactNode;
  labelledBy?: string;
  /** Panel max width */
  size?: BlurModalSize;
};

const SIZE_CLASS: Record<BlurModalSize, string> = {
  sm: 'max-w-lg',
  md: 'max-w-2xl',
  lg: 'max-w-4xl',
  xl: 'max-w-6xl',
};

/**
 * Centered glass dialog: light translucent overlay + strong blur (no heavy grey dim).
 */
export const BlurModal: React.FC<BlurModalProps> = ({
  open,
  onClose,
  children,
  labelledBy,
  size = 'lg',
}) => {
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      document.body.style.overflow = prev;
      window.removeEventListener('keydown', onKey);
    };
  }, [open, onClose]);

  if (!open || typeof document === 'undefined') return null;

  const maxW = SIZE_CLASS[size];

  return createPortal(
    <div
      className="fixed inset-0 z-[85] flex items-center justify-center bg-slate-900/[0.07] p-3 backdrop-blur-xl sm:p-5"
      role="dialog"
      aria-modal
      aria-labelledby={labelledBy}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={`flex max-h-[min(90dvh,900px)] w-full ${maxW} flex-col overflow-hidden rounded-2xl border border-white/60 bg-white/80 shadow-[0_24px_80px_rgba(15,23,42,0.12)] backdrop-blur-2xl sm:rounded-3xl`}
        onMouseDown={(e) => e.stopPropagation()}
      >
        {children}
      </div>
    </div>,
    document.body,
  );
};

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { MainLayout } from '../../layout/MainLayout';
import {
  fetchIntegrations,
  fetchIntegrationHubCatalog,
  syncIntegration,
  testIntegration,
  type IntegrationConnectionDto,
  type IntegrationHubCatalogEntry,
} from '../../api/integrations';
import { IntegrationConnectionCard } from '../../components/integrations/IntegrationConnectionCard';
import { IntegrationConnectionTestSyncActions } from '../../components/integrations/IntegrationConnectionTestSyncActions';
import {
  MarketingIntegrationsPanel,
} from '../marketing/MarketingIntegrationsPanel';

type HubTab = 'connections' | 'marketing';

const TAB_IDS: HubTab[] = ['connections', 'marketing'];

function isHubCatalogConnection(
  c: IntegrationConnectionDto,
  catalogIds: Set<string>,
): boolean {
  if (c.kind === 'woocommerce') return catalogIds.has('woocommerce');
  return Boolean(
    c.kind === 'third_party_link' && c.linkCatalogId && catalogIds.has(c.linkCatalogId),
  );
}

export const IntegrationsHubPage: React.FC = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const rawTab = searchParams.get('tab') || '';

  const activeTab: HubTab =
    rawTab === 'marketing' && TAB_IDS.includes('marketing')
      ? 'marketing'
      : 'connections';

  const setTab = (tab: HubTab) => {
    setSearchParams(tab === 'connections' ? {} : { tab: 'marketing' });
  };

  useEffect(() => {
    if (rawTab === 'catalog' || rawTab === 'store') {
      navigate('/automations?tab=integrations', { replace: true });
    }
  }, [rawTab, navigate]);

  useEffect(() => {
    if (searchParams.get('woo') === '1') {
      navigate('/automations?tab=integrations&woo=1', { replace: true });
    }
  }, [searchParams, navigate]);

  const [catalog, setCatalog] = useState<IntegrationHubCatalogEntry[]>([]);
  const [connections, setConnections] = useState<IntegrationConnectionDto[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [testingId, setTestingId] = useState<string | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [actionMsg, setActionMsg] = useState<string | null>(null);

  const load = useCallback(async (opts?: { quiet?: boolean }) => {
    const quiet = Boolean(opts?.quiet);
    if (!quiet) {
      setLoading(true);
      setError(null);
    }
    try {
      const [cat, conn] = await Promise.all([
        fetchIntegrationHubCatalog(),
        fetchIntegrations(),
      ]);
      setCatalog(Array.isArray(cat) ? cat : []);
      setConnections(Array.isArray(conn) ? conn : []);
    } catch (e) {
      if (!quiet) {
        setError((e as Error)?.message || t('crm.integrationsHub.loadError'));
      }
    } finally {
      if (!quiet) setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    void load();
  }, [load]);

  const catalogIds = useMemo(() => new Set(catalog.map((e) => e.id)), [catalog]);

  const hubConnections = useMemo(
    () => connections.filter((c) => isHubCatalogConnection(c, catalogIds)),
    [connections, catalogIds],
  );

  const otherConnections = useMemo(
    () => connections.filter((c) => !hubConnections.some((h) => h.id === c.id)),
    [connections, hubConnections],
  );

  const handleTest = async (id: string) => {
    setTestingId(id);
    setActionMsg(null);
    try {
      const r = await testIntegration(id);
      setActionMsg(
        r.ok ? r.message || 'OK' : r.message || t('crm.integrationsHub.testFailed'),
      );
    } catch (e) {
      setActionMsg((e as Error).message);
    } finally {
      setTestingId(null);
    }
  };

  const handleSync = async (id: string) => {
    setSyncingId(id);
    setActionMsg(null);
    try {
      const r = await syncIntegration(id);
      const tail =
        r.created !== undefined || r.updated !== undefined
          ? ` (+${r.created}/${r.updated})`
          : '';
      setActionMsg(
        (r.message ||
          (r.ok ? t('crm.integrationsHub.syncOk') : t('crm.integrationsHub.syncFail'))) + tail,
      );
      await load();
    } catch (e) {
      setActionMsg((e as Error).message);
    } finally {
      setSyncingId(null);
    }
  };

  const tabBtn = (tab: HubTab) => {
    const on = activeTab === tab;
    return (
      <button
        key={tab}
        type="button"
        onClick={() => setTab(tab)}
        className={`rounded-full px-4 py-2 text-xs font-semibold transition-all duration-200 active:scale-[0.98] ${
          on
            ? 'bg-[#222222] text-white shadow-md shadow-slate-900/15'
            : 'border border-slate-200/90 bg-white text-slate-700 shadow-sm hover:-translate-y-0.5 hover:border-slate-300 hover:bg-slate-50/90 hover:shadow-md'
        }`}
      >
        {t(`crm.integrationsHub.tabs.${tab}`)}
      </button>
    );
  };

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <h1 className="text-lg font-semibold text-slate-900">
              {t('crm.integrationsHub.title')}
            </h1>
            <p className="text-xs text-slate-600 mt-1 max-w-3xl leading-relaxed">
              {t('crm.integrationsHub.subtitle')}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="rounded-full border border-slate-200/90 bg-white px-4 py-2 text-xs font-semibold text-slate-800 shadow-sm transition-all duration-200 hover:-translate-y-0.5 hover:bg-slate-50 hover:shadow-md active:scale-[0.98] disabled:opacity-50 disabled:hover:translate-y-0"
            >
              {t('crm.integrationsHub.refresh')}
            </button>
            <Link
              to="/automations?tab=integrations"
              className="inline-flex items-center justify-center rounded-full border border-slate-200/90 bg-white px-4 py-2 text-xs font-semibold text-slate-800 shadow-sm transition-all duration-200 hover:-translate-y-0.5 hover:bg-slate-50 hover:shadow-md active:scale-[0.98]"
            >
              {t('crm.integrationsHub.openAutomationsIntegrations')}
            </Link>
          </div>
        </div>

        <div className="flex flex-wrap gap-2">
          {tabBtn('connections')}
          {tabBtn('marketing')}
        </div>

        {actionMsg && (
          <div className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs text-slate-800">
            {actionMsg}
          </div>
        )}

        {loading && (
          <p className="text-xs text-slate-500">{t('crm.automations.list.loading')}</p>
        )}
        {error && (
          <div className="rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-xs text-rose-800">
            {error}
          </div>
        )}

        {!loading && !error && activeTab === 'connections' && (
          <section className="space-y-3">
            <h2 className="text-sm font-semibold text-slate-900">
              {t('crm.integrationsHub.connectionsHeading')}
            </h2>
            {connections.length === 0 ? (
              <p className="text-sm text-slate-500">{t('crm.integrationsHub.connectionsEmpty')}</p>
            ) : (
              <div className="space-y-6">
                {hubConnections.length > 0 && (
                  <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                    {hubConnections.map((c) => (
                      <IntegrationConnectionCard
                        key={c.id}
                        cardClassName="transition-all duration-200 hover:-translate-y-0.5 hover:shadow-lg hover:border-slate-300/90"
                        connection={c}
                        t={t}
                        connectorSubtitle={
                          c.kind === 'woocommerce' ||
                          (c.kind === 'third_party_link' && c.linkCatalogId)
                            ? 'plainCatalog'
                            : false
                        }
                        lastSyncVariant="hub"
                        showLastSyncStatus
                        footer={
                          <IntegrationConnectionTestSyncActions
                            connectionId={c.id}
                            testingId={testingId}
                            syncingId={syncingId}
                            onTest={handleTest}
                            onSync={handleSync}
                            t={t}
                          />
                        }
                      />
                    ))}
                  </div>
                )}

                {otherConnections.length > 0 && (
                  <div>
                    <h3 className="text-xs font-semibold text-slate-600 mb-2">
                      {t('crm.integrationsHub.otherConnectionsHeading')}
                    </h3>
                    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                      {otherConnections.map((c) => (
                        <IntegrationConnectionCard
                          key={c.id}
                          cardClassName="transition-all duration-200 hover:-translate-y-0.5 hover:shadow-lg hover:border-slate-300/80"
                          connection={c}
                          t={t}
                          surfaceTone="whiteDashed"
                          connectorSubtitle={false}
                          metaLine={
                            <div className="text-[10px] text-slate-500 mt-0.5">
                              {t('crm.integrationsHub.kind')}: {c.kind}
                              {c.linkCatalogId ? ` · ${c.linkCatalogId}` : ''}
                            </div>
                          }
                          lastSyncVariant="hub"
                          showLastSyncStatus
                          showSalesIntegrationsLink={
                            c.kind === 'woocommerce' || c.kind === 'manual-import'
                          }
                          footer={
                            <IntegrationConnectionTestSyncActions
                              connectionId={c.id}
                              testingId={testingId}
                              syncingId={syncingId}
                              onTest={handleTest}
                              onSync={handleSync}
                              t={t}
                            />
                          }
                        />
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
            <p className="text-xs text-slate-600 leading-relaxed">
              {t('crm.integrationsHub.hubConnectionsHint')}
            </p>
          </section>
        )}

        {!loading && !error && activeTab === 'marketing' && (
          <MarketingIntegrationsPanel
            variant="embedded"
            onMarketingDataChanged={() => void load({ quiet: true })}
          />
        )}
      </div>
    </MainLayout>
  );
};

