const openRoadmapConnect = (item: IntegrationCatalogItem) => {
  setConnectTarget(item);
  setConnectDraft({
    label: '',
    webhookUrl: '',
    apiToken: '',
    accountEmail: '',
    phoneNumberId: '',
    calendarId: '',
    developerToken: '',
    webhookVerifyToken: '',
    amoWebhookSecret: '',
    webhookInboundSecret: '',
    spreadsheetId: '',
  });
  setConnectErr(null);
};

const submitRoadmapConnect = async () => {
  if (!connectTarget) return;
  if (connectTarget.id === 'mailchimp' && connectDraft.apiToken.trim().length < 12) {
    setConnectErr(t('crm.automations.panel.integrations.connectMailchimpTokenShort'));
    return;
  }
  if (connectTarget.id === 'wordpress_cf7') {
    const sec = connectDraft.webhookInboundSecret.trim();
    if (sec.length > 0 && sec.length < 6) {
      setConnectErr(t('crm.automations.panel.integrations.connectWordpressCf7SecretShort'));
      return;
    }
  }
  if (connectTarget.id === 'google_sheets') {
    const sid = connectDraft.spreadsheetId.trim();
    if (!sid) {
      setConnectErr(t('crm.automations.panel.integrations.connectGoogleSheetsSpreadsheetRequired'));
      return;
    }
    if (!/^[a-zA-Z0-9-_]{20,}$/.test(sid)) {
      setConnectErr(t('crm.automations.panel.integrations.connectGoogleSheetsSpreadsheetInvalid'));
      return;
    }
    if (connectDraft.apiToken.trim().length < 12) {
      setConnectErr(t('crm.automations.panel.integrations.connectGoogleSheetsTokenShort'));
      return;
    }
  }
  setConnectBusy(true);
  setConnectErr(null);
  try {
    const catalogTitle = integrationCatalogName(connectTarget.id, t);
    const name =
      connectDraft.label.trim() ||
      `${catalogTitle} — ${t('crm.automations.panel.integrations.connectDefaultSuffix')}`;
    const created = await createIntegration({
      name,
      kind: 'third_party_link',
      description: catalogTitle,
      config: {
        catalogId: connectTarget.id,
        label: connectDraft.label.trim() || undefined,
        webhookUrl: connectDraft.webhookUrl.trim() || undefined,
        apiToken: connectDraft.apiToken.trim() || undefined,
        accountEmail: connectDraft.accountEmail.trim() || undefined,
        phoneNumberId: connectDraft.phoneNumberId.trim() || undefined,
        calendarId: connectDraft.calendarId.trim() || undefined,
        developerToken: connectDraft.developerToken.trim() || undefined,
        webhookVerifyToken: connectDraft.webhookVerifyToken.trim() || undefined,
        ...(connectTarget.id === 'amocrm'
          ? { amoWebhookSecret: connectDraft.amoWebhookSecret.trim() || undefined }
          : {}),
        ...(connectTarget.id === 'wordpress_cf7'
          ? {
              webhookInboundSecret:
                connectDraft.webhookInboundSecret.trim() || undefined,
            }
          : {}),
        ...(connectTarget.id === 'google_sheets'
          ? { spreadsheetId: connectDraft.spreadsheetId.trim() }
          : {}),
      },
    });
    await testIntegration(created.id).catch(() => {});
    setConnectTarget(null);
    const [nextConn, nextMkt] = await Promise.all([
      fetchIntegrations(),
      fetchMarketingIntegrations().catch(() => [] as MarketingIntegrationRow[]),
    ]);
    setConnections(nextConn);
    setMarketingIntegrations(Array.isArray(nextMkt) ? nextMkt : []);
  } catch (e: unknown) {
    setConnectErr(
      (e as Error)?.message || t('crm.automations.panel.integrations.connectError'),
    );
  } finally {
    setConnectBusy(false);
  }
};

