/**
 * @param mixed $input
 * @return array<string, mixed>
 */
public function sanitize_connector_options( $input ): array {
    $prev = get_option( 'lumiva_crm_connector_options', [] );
    if ( ! is_array( $prev ) ) {
        $prev = [];
    }
    if ( ! is_array( $input ) ) {
        return $prev;
    }
    $out = array_merge( $prev, $input );
    if ( isset( $input['api_token'] ) ) {
        $out['api_token'] = trim( (string) $input['api_token'] );
    }
    $out['cf7_enabled'] = ! empty( $input['cf7_enabled'] ) ? 1 : 0;
    $out['debug_log']   = ! empty( $input['debug_log'] ) ? 1 : 0;
    foreach ( [ 'cf7_name_field', 'cf7_phone_field', 'cf7_email_field', 'cf7_message_field' ] as $k ) {
        if ( isset( $input[ $k ] ) ) {
            $out[ $k ] = sanitize_text_field( (string) $input[ $k ] );
        }
    }
    return $out;
}

