      const eRow = effective.find((m) => m.key === key);
      return {
        key,
        tenantEnabled: Boolean(tRow?.enabled),
        siteOverride: pickSiteModuleOverride(key, overrides) ?? null,
        effective: Boolean(eRow?.enabled),
        allowedByPlan: Boolean(tRow?.allowedByPlan),
      };
    });
  }
}

