private getLumivaWizardAddonTenantModuleKey(
  catalogId: string | undefined,
): 'clientcabinet' | 'chat' | null {
  if (!catalogId) return null;
  return LUMIVA_WIZARD_ADDON_CATALOG_TO_TENANT_MODULE[catalogId] ?? null;
}

private parseThirdPartyLinkCatalogId(entity: IntegrationConnection): string | null {

/**
 * Не более одного неудалённого подключения Lumiva Wizard (кабинет / чат) на каталог на тенанта.
 */
private async assertUniqueLumivaWizardAddonConnection(
  tenantId: string,
  catalogId: string,
  excludeConnectionId?: string,
): Promise<void> {
  if (!LUMIVA_WIZARD_ADDON_UNIQUE_CATALOG_IDS.has(catalogId)) return;

  const rows = await this.repo.find({
    where: { tenantId, isDeleted: false, kind: 'third_party_link' } as any,
  });
  for (const row of rows) {
    if (excludeConnectionId && row.id === excludeConnectionId) continue;
    if (this.parseThirdPartyLinkCatalogId(row) === catalogId) {
      throw new BadRequestException(
        'У компании уже есть подключение этого типа (Lumiva Wizard). Удалите или отключите существующее, затем создайте новое.',
      );
    }
  }
}

private async applyLumivaWizardAddonFromConnection(
  tenantId: string,
  entity: IntegrationConnection,
): Promise<void> {
  if (entity.kind !== 'third_party_link' || !entity.configJson) return;
  let catalogId: string | undefined;
  try {
    catalogId = (JSON.parse(entity.configJson) as { catalogId?: string }).catalogId;
  } catch {
    return;
  }
  const moduleKey = this.getLumivaWizardAddonTenantModuleKey(
    typeof catalogId === 'string' ? catalogId : undefined,
  );
  if (!moduleKey) return;
  const on = Boolean(entity.isEnabled && !entity.isDeleted);
  await this.tenantsService.toggleTenantModule(tenantId, moduleKey, on);
}

