private toSegmentDto(e: MarketingSegment): SegmentDto {
    return {
    id: e.id,
    entityType: 'lead',
    name: e.name,
    description: e.description,
    leadStatuses: e.leadStatuses,
    source: e.source,
    country: e.country,
