import { IsIn, IsOptional, IsString, IsUUID, MaxLength } from 'class-validator';

export class GoogleCalendarOAuthStartDto {
  /** Относительный путь фронта после OAuth, например /integrations-hub?tab=connections */
  @IsOptional()
  @IsString()
  @MaxLength(400)
  redirectPath?: string;

  @IsIn(['create', 'reconnect'])
  intent!: 'create' | 'reconnect';

  @IsOptional()
  @IsUUID()
  integrationId?: string;

  @IsOptional()
  @IsString()
  @MaxLength(200)
  name?: string;

  /** ID календаря Google (email или primary); по умолчанию primary */
  @IsOptional()
  @IsString()
  @MaxLength(500)
  calendarId?: string;
}

import { Injectable } from '@nestjs/common';
import axios from 'axios';

const CAL_BASE = 'https://www.googleapis.com/calendar/v3';

export type GoogleCalendarEventItem = {
  id?: string;
  summary?: string;
  description?: string;
  start?: { dateTime?: string; timeZone?: string; date?: string };
  end?: { dateTime?: string; timeZone?: string; date?: string };
  extendedProperties?: { private?: Record<string, string> };
};

/**
 * Google Calendar API — проверка доступа, CRUD событий (OAuth access / refresh token).
 * @see https://developers.google.com/calendar/api/v3/reference
 */
@Injectable()
export class GoogleCalendarService {
  private pathCal(calendarId: string): string {
    const cal = (calendarId || 'primary').trim() || 'primary';
    return cal === 'primary' ? 'primary' : encodeURIComponent(cal);
  }

  async refreshAccessToken(params: {
    clientId: string;
    clientSecret: string;
    refreshToken: string;
  }): Promise<{ accessToken: string; expiresIn?: number }> {
    const { clientId, clientSecret, refreshToken } = params;
    const rt = refreshToken.trim();
    if (!rt) throw new Error('Google Calendar: пустой refresh token');
    const body = new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: rt,
      grant_type: 'refresh_token',
    });
    const res = await axios.post('https://oauth2.googleapis.com/token', body.toString(), {
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      timeout: 20000,
      validateStatus: () => true,
    });
    if (res.status !== 200) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google OAuth refresh: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
    const accessToken = String(res.data?.access_token ?? '').trim();
    if (!accessToken) {
      throw new Error('Google OAuth refresh: нет access_token в ответе');
    }
    const expiresIn =
      typeof res.data?.expires_in === 'number' ? res.data.expires_in : undefined;
    return { accessToken, expiresIn };
  }

  async verifyCalendarAccess(accessToken: string): Promise<void> {
    const tok = accessToken.trim();
    if (!tok) {
      throw new Error('Google Calendar: пустой access token');
    }
    const res = await axios.get(`${CAL_BASE}/users/me/calendarList`, {
      headers: { Authorization: `Bearer ${tok}` },
      params: { maxResults: 1 },
      timeout: 15000,
      validateStatus: () => true,
    });
    if (res.status !== 200) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google Calendar API: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
  }

  async insertEvent(params: {
    accessToken: string;
    calendarId: string;
    summary: string;
    description?: string;
    startIso: string;
    endIso: string;
    timeZone: string;
    extendedProperties?: { private?: Record<string, string> };
  }): Promise<{ id?: string }> {
    const {
      accessToken,
      calendarId,
      summary,
      description,
      startIso,
      endIso,
      timeZone,
      extendedProperties,
    } = params;
    const tok = accessToken.trim();
    if (!tok) {
      throw new Error('Google Calendar: пустой access token');
    }
    const pathCal = this.pathCal(calendarId);

    const res = await axios.post(
      `${CAL_BASE}/calendars/${pathCal}/events`,
      {
        summary: summary.slice(0, 1024),
        ...(description ? { description: description.slice(0, 8000) } : {}),
        start: { dateTime: startIso, timeZone: timeZone || 'UTC' },
        end: { dateTime: endIso, timeZone: timeZone || 'UTC' },
        ...(extendedProperties?.private && Object.keys(extendedProperties.private).length
          ? { extendedProperties }
          : {}),
      },
      {
        headers: {
          Authorization: `Bearer ${tok}`,
          'Content-Type': 'application/json',
        },
        timeout: 25000,
        validateStatus: () => true,
      },
    );
    if (res.status !== 200 && res.status !== 201) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google Calendar: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
    return res.data as { id?: string };
  }

  async patchEvent(params: {
    accessToken: string;
    calendarId: string;
    eventId: string;
    summary: string;
    description?: string;
    startIso: string;
    endIso: string;
    timeZone: string;
    extendedProperties?: { private?: Record<string, string> };
  }): Promise<void> {
    const tok = params.accessToken.trim();
    if (!tok) throw new Error('Google Calendar: пустой access token');
    const pathCal = this.pathCal(params.calendarId);
    const eid = encodeURIComponent(params.eventId);
    const body: Record<string, unknown> = {
      summary: params.summary.slice(0, 1024),
      ...(params.description ? { description: params.description.slice(0, 8000) } : {}),
      start: { dateTime: params.startIso, timeZone: params.timeZone || 'UTC' },
      end: { dateTime: params.endIso, timeZone: params.timeZone || 'UTC' },
    };
    if (
      params.extendedProperties?.private &&
      Object.keys(params.extendedProperties.private).length
    ) {
      body.extendedProperties = params.extendedProperties;
    }
    const res = await axios.patch(`${CAL_BASE}/calendars/${pathCal}/events/${eid}`, body, {
      headers: {
        Authorization: `Bearer ${tok}`,
        'Content-Type': 'application/json',
      },
      timeout: 25000,
      validateStatus: () => true,
    });
    if (res.status !== 200) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google Calendar patch: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
  }

  async deleteEvent(params: {
    accessToken: string;
    calendarId: string;
    eventId: string;
  }): Promise<void> {
    const tok = params.accessToken.trim();
    if (!tok) throw new Error('Google Calendar: пустой access token');
    const pathCal = this.pathCal(params.calendarId);
    const eid = encodeURIComponent(params.eventId);
    const res = await axios.delete(`${CAL_BASE}/calendars/${pathCal}/events/${eid}`, {
      headers: { Authorization: `Bearer ${tok}` },
      timeout: 20000,
      validateStatus: () => true,
    });
    if (res.status !== 204 && res.status !== 200 && res.status !== 410) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google Calendar delete: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
  }

  async listEvents(params: {
    accessToken: string;
    calendarId: string;
    timeMinIso: string;
    timeMaxIso: string;
    privateExtendedProperty?: string;
  }): Promise<GoogleCalendarEventItem[]> {
    const tok = params.accessToken.trim();
    if (!tok) throw new Error('Google Calendar: пустой access token');
    const pathCal = this.pathCal(params.calendarId);
    const q: Record<string, string> = {
      singleEvents: 'true',
      orderBy: 'startTime',
      timeMin: params.timeMinIso,
      timeMax: params.timeMaxIso,
      maxResults: '250',
    };
    if (params.privateExtendedProperty) {
      q.privateExtendedProperty = params.privateExtendedProperty;
    }
    const res = await axios.get(`${CAL_BASE}/calendars/${pathCal}/events`, {
      headers: { Authorization: `Bearer ${tok}` },
      params: q,
      timeout: 30000,
      validateStatus: () => true,
    });
    if (res.status !== 200) {
      const detail =
        typeof res.data === 'object' && res.data !== null
          ? JSON.stringify(res.data)
          : String(res.data ?? '');
      throw new Error(`Google Calendar list: HTTP ${res.status} ${detail}`.slice(0, 500));
    }
    const items = (res.data as { items?: GoogleCalendarEventItem[] })?.items;
    return Array.isArray(items) ? items : [];
  }
}

import * as crypto from 'crypto';

import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import axios from 'axios';

import { PlatformSettingsService } from '../../platform-settings/platform-settings.service';
import { IntegrationsService } from '../integrations.service';
import type { GoogleCalendarOAuthStartDto } from '../dto/google-calendar-oauth-start.dto';

const STATE_TYP = 'lumiva_gcal_oauth_v1' as const;
const TTL_SEC = 900;

type GcalOauthState = {
  typ: typeof STATE_TYP;
  exp: number;
  tenantId: string;
  userId: string;
  redirect: string;
  intent: 'create' | 'reconnect';
  integrationId?: string;
  draft?: {
    name: string;
    calendarId: string;
  };
};

@Injectable()
export class GoogleCalendarOAuthService {
  private readonly log = new Logger(GoogleCalendarOAuthService.name);

  constructor(
    private readonly platformSettings: PlatformSettingsService,
    private readonly integrations: IntegrationsService,
  ) {}

  private secret(): string {
    return process.env.JWT_SECRET || 'changeme';
  }

  private callbackRedirectUri(): string {
    const apiBase = (process.env.PUBLIC_API_URL || '').replace(/\/$/, '');
    return `${apiBase}/v1/integrations/google-calendar/oauth/callback`;
  }

  private sanitizeFrontendPath(raw: string | undefined): string {
    const fallback = '/integrations-hub?tab=connections';
    const s = (raw ?? '').trim();
    if (!s) return fallback;
    if (!s.startsWith('/') || s.startsWith('//') || s.includes('://')) {
      throw new BadRequestException(
        'redirectPath должен быть относительным путём, начинающимся с /',
      );
    }
    if (s.length > 400) return fallback;
    return s;
  }

  private encodeState(inner: Omit<GcalOauthState, 'typ' | 'exp'>): string {
    const exp = Math.floor(Date.now() / 1000) + TTL_SEC;
    const body: GcalOauthState = { typ: STATE_TYP, exp, ...inner };
    const payload = Buffer.from(JSON.stringify(body), 'utf8').toString('base64url');
    const sig = crypto
      .createHmac('sha256', this.secret())
      .update(payload)
      .digest('base64url');
    return `${payload}.${sig}`;
  }

  decodeState(state: string): GcalOauthState | null {
    try {
      const dot = state.indexOf('.');
      if (dot <= 0) return null;
      const payloadB64 = state.slice(0, dot);
      const sig = state.slice(dot + 1);
      const expected = crypto
        .createHmac('sha256', this.secret())
        .update(payloadB64)
        .digest('base64url');
      const a = Buffer.from(sig);
      const b = Buffer.from(expected);
      if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
      const data = JSON.parse(
        Buffer.from(payloadB64, 'base64url').toString('utf8'),
      ) as GcalOauthState;
      if (data?.typ !== STATE_TYP) return null;
      if (!data?.tenantId || typeof data.redirect !== 'string') return null;
      if (data.intent !== 'create' && data.intent !== 'reconnect') return null;
      if (typeof data.exp !== 'number' || !Number.isFinite(data.exp)) return null;
      return data;
    } catch {
      return null;
    }
  }

  async buildAuthorizeUrl(
    tenantId: string,
    userId: string,
    dto: GoogleCalendarOAuthStartDto,
  ): Promise<string> {
    const { clientId, clientSecret } = await this.platformSettings.getGoogleOAuthConfig();
    if (!clientId || !clientSecret) {
      throw new BadRequestException(
        'Google OAuth не настроен на платформе (client id / secret). Укажите GOOGLE_OAUTH_CLIENT_*.',
      );
    }
    const apiBase = (process.env.PUBLIC_API_URL || '').replace(/\/$/, '');
    if (!apiBase) {
      throw new BadRequestException(
        'PUBLIC_API_URL не задан — без него нельзя зарегистрировать redirect_uri в Google Cloud.',
      );
    }
    const redirect = this.sanitizeFrontendPath(dto.redirectPath);

    if (dto.intent === 'reconnect') {
      const iid = dto.integrationId?.trim();
      if (!iid) {
        throw new BadRequestException('Для переподключения укажите integrationId');
      }
      const row = await this.integrations.findEntityRaw(tenantId, iid);
      if (!row || row.kind !== 'third_party_link' || !row.configJson) {
        throw new NotFoundException('Подключение не найдено');
      }
      let catalogId = '';
      try {
        catalogId = String(
          (JSON.parse(row.configJson) as { catalogId?: string }).catalogId || '',
        );
      } catch {
        catalogId = '';
      }
      if (catalogId !== 'google_calendar') {
        throw new BadRequestException('Подключение не является Google Calendar');
      }
      const state = this.encodeState({
        tenantId,
        userId,
        redirect,
        intent: 'reconnect',
        integrationId: iid,
      });
      return this.authorizeUrlWithState(clientId, state);
    }

    const name =
      (dto.name && dto.name.trim()) ||
      `Google Calendar — ${new Date().toISOString().slice(0, 10)}`;
    const calendarId = (dto.calendarId && dto.calendarId.trim()) || 'primary';

    const state = this.encodeState({
      tenantId,
      userId,
      redirect,
      intent: 'create',
      draft: { name, calendarId },
    });
    return this.authorizeUrlWithState(clientId, state);
  }

  private authorizeUrlWithState(clientId: string, state: string): string {
    const redirectUri = this.callbackRedirectUri();
    const params = new URLSearchParams({
      client_id: clientId,
      redirect_uri: redirectUri,
      response_type: 'code',
      access_type: 'offline',
      prompt: 'consent',
      scope: 'https://www.googleapis.com/auth/calendar.events',
      include_granted_scopes: 'true',
      state,
    });
    return `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
  }

  private async exchangeCodeForRefreshToken(
    code: string,
    redirectUri: string,
  ): Promise<string> {
    const { clientId, clientSecret } = await this.platformSettings.getGoogleOAuthConfig();
    if (!clientId || !clientSecret) {
      throw new BadRequestException('Google OAuth is not configured');
    }
    const params = new URLSearchParams({
      code,
      client_id: clientId,
      client_secret: clientSecret,
      redirect_uri: redirectUri,
      grant_type: 'authorization_code',
    });
    const res = await axios.post(
      'https://oauth2.googleapis.com/token',
      params.toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
    );
    const rt = res.data?.refresh_token as string | undefined;
    if (!rt) {
      throw new BadRequestException('No refresh_token from Google (try prompt=consent)');
    }
    return rt;
  }

  /**
   * @returns относительный путь на фронт с query googleCalendarOAuth=connected|error
   */
  async completeRedirect(code: string, state: string): Promise<string> {
    const withError = (path: string) => {
      const sep = path.includes('?') ? '&' : '?';
      return `${path}${sep}googleCalendarOAuth=error`;
    };
    const withOk = (path: string) => {
      const sep = path.includes('?') ? '&' : '?';
      return `${path}${sep}googleCalendarOAuth=connected`;
    };

    const decoded = this.decodeState(state);
    if (!decoded) {
      return withError('/integrations-hub?tab=connections');
    }
    const now = Math.floor(Date.now() / 1000);
    if (decoded.exp < now - 60) {
      return withError(decoded.redirect);
    }

    const redirectUri = this.callbackRedirectUri();
    let refreshToken: string;
    try {
      refreshToken = await this.exchangeCodeForRefreshToken(code, redirectUri);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      this.log.warn(`Google Calendar OAuth code exchange failed: ${msg}`);
      return withError(decoded.redirect);
    }

    try {
      if (decoded.intent === 'reconnect' && decoded.integrationId) {
        await this.integrations.patchGoogleCalendarOAuthTokens(
          decoded.tenantId,
          decoded.integrationId,
          refreshToken,
        );
        return withOk(decoded.redirect);
      }

      if (decoded.intent === 'create' && decoded.draft) {
        const d = decoded.draft;
        await this.integrations.createGoogleCalendarOAuthConnection(decoded.tenantId, {
          name: d.name,
          calendarId: d.calendarId,
          oauthRefreshToken: refreshToken,
        });
        return withOk(decoded.redirect);
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      this.log.error(`Google Calendar OAuth finalize failed: ${msg}`);
      return withError(decoded.redirect);
    }

    return withError(decoded.redirect);
  }
}

