  const {
    accessToken,
    calendarId,
    summary,
    description,
    startIso,
    endIso,
    timeZone,
    extendedProperties,
    createMeetConference = true,
  } = params;
  const tok = accessToken.trim();
  if (!tok) {
    throw new Error('Google Calendar: пустой access token');
